import { defineChapterTopic, type ChapterAuthorSpec } from '../chapter-package-engine';
import type { EducationTopic } from '../education-types';

const HAEM_DISCLAIMER =
  'Educational haematology and laboratory medicine principles only. Reference intervals vary by assay, instrument, and patient age/sex; never use these teaching examples to interpret personal medical test results.';

const HAEM_ASSET_GAP = {
  status: 'asset_required' as const,
  summary:
    'Blood lineage mechanisms, RBC indices (MCV/MCHC/RDW), coagulation cascade PT/aPTT interpretation, urinalysis, and clinical chemistry frameworks are implemented. Genuine licensed Wright-Giemsa peripheral blood smear & bone-marrow aspirate photomicrographs are NOT yet bundled locally (link external Utah WebPath & UMich; zero synthetic blood smears substituted).',
  missingAssets: ['Licensed Wright-Giemsa peripheral blood smear, reticulocyte, and bone-marrow morphology photomicrographs'],
};

function makeHaemChapter(
  num: number,
  id: string,
  chapterTitle: string,
  title: string,
  summary: string,
  labSpec: string,
  comp: { colA: string; colB: string; rows: ChapterAuthorSpec['comparisonTable']['rows'] },
  mechanisms: string[],
  clinical: string,
  fmas: string[],
  sys: ChapterAuthorSpec['relatedSystems'],
  mcqs: ChapterAuthorSpec['selfChecks'],
): ChapterAuthorSpec {
  return {
    id,
    domainId: 'haematology_lab',
    chapterCode: `M${num}`,
    chapterOrder: num,
    chapterTitle,
    title,
    summary,
    targetTracks: ['secondary_premed', 'medical_foundations', 'clinical_applied', 'allied_health', 'graduate_research'],
    curriculumMappings: [
      { frameworkId: 'pk_pmdc_mbbs', gradeOrYear: 'MBBS Years 2–4', unitOrModule: `Haematology & Chemical Pathology (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'pk_uhs_mbbs', gradeOrYear: 'MBBS Professional II', unitOrModule: `Clinical Pathology & Blood Banking (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'hms_pathways', gradeOrYear: 'MD Core Clerkships', unitOrModule: `Diagnostics & Lab Medicine (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'qaa_biosciences', gradeOrYear: 'BS Hons / MPhil', unitOrModule: `Clinical Biochemistry & Flow Cytometry (${chapterTitle})`, status: 'recommended' },
    ],
    prerequisites: ['Erythrocyte/leukocyte histology (C6)', 'Protein/haem biochemistry (F2, F19)'],
    learningObjectives: [
      `Explain cellular haematopoiesis, biochemical assays, or physiological mechanisms governing ${chapterTitle.toLowerCase()}.`,
      `Interpret structured teaching laboratory profiles and peripheral smear morphology descriptions (${labSpec}).`,
      `Recognize pre-analytical collection errors, haemolysis artefacts, and critical panic values without misusing educational material clinically.`,
    ],
    depthExplanations: {
      secondary_premed: `${summary} Blood cells, platelets, and plasma proteins work continuously to deliver oxygen, clot wounds safely, and clear microbes.`,
      medical_foundations: `${mechanisms.join(' ')} Teaching Lab Summary: ${labSpec}. Note: inspect external Utah WebPath smears while local blood smear images remain Asset Required.`,
      clinical_applied: `Diagnostic reasoning in ${chapterTitle.toLowerCase()} integrates MCV/reticulocyte counts, PT/aPTT mixing, electrolyte anion gaps, and transfusion crossmatching: ${clinical}`,
      allied_health: `Specimen tube order-of-draw (blue citrate, red serum, green heparin, purple EDTA, grey fluoride), haemolysis avoidance, and transfusion safety checks in ${chapterTitle.toLowerCase()}: ${labSpec}`,
      graduate_research: `Flow cytometric minimal residual disease gating, thromboelastography (TEG), mass spectrometry biomarkers, and next-generation myeloid genomics in ${chapterTitle.toLowerCase()}.`,
    },
    keyConcepts: [
      { term: 'Haematologic / Lab Basis', definition: summary },
      { term: 'Diagnostic Assay & Tubes', definition: labSpec },
      { term: 'Clinical Interpretation', definition: clinical },
    ],
    keyFacts: [
      `Assay & Specimen Context: ${labSpec}.`,
      HAEM_DISCLAIMER,
    ],
    mechanisms,
    comparisonTable: { columnA: comp.colA, columnB: comp.colB, rows: comp.rows },
    misconceptions: [
      { misconception: 'Drawing blood into the wrong anticoagulant tube only slightly alters electrolytes.', correction: 'Purple EDTA tubes chelate calcium and add massive potassium (K3-EDTA): contaminating a chemistry tube creates fake serum K+ >12 mM with Ca2+ <1 mg/dL!' },
      { misconception: 'A normal MCV excludes coexisting iron and vitamin B12 deficiencies.', correction: 'Concurrent microcytosis (iron) and macrocytosis (B12/folate) yield a normal average MCV paired with a markedly elevated RDW ("dimorphic" dual population).' },
    ],
    clinicalCorrelation: clinical,
    summaryParagraph: `${chapterTitle} synthesizes erythrocyte/leukocyte biology, coagulation kinetics, blood banking, and core clinical lab interpretation. Authentic local blood smears remain honestly marked Asset Required.`,
    keyTakeaways: [
      mechanisms[0] ?? summary,
      labSpec,
      clinical,
    ],
    crossSubjectLinks: [
      { domainId: 'pathology', relation: 'Bone-marrow neoplasia, DIC, and haemolytic microangiopathies bridge benign & malignant blood pathology.' },
      { domainId: 'pharmacology', relation: 'Anticoagulants, antiplatelets, erythropoietin, and chelators alter lab tests directly.' },
    ],
    relatedSystems: sys,
    relatedFmaConceptIds: fmas,
    visualFormats: ['2d_diagram', 'microscopy', 'clinical_case'],
    diagram: {
      id: `diag-m${num}`,
      title: `${chapterTitle} — Physiological & Diagnostic Lab Algorithm`,
      kind: 'pathway',
      caption: `${summary} (${labSpec})`,
      disclaimer: HAEM_DISCLAIMER,
      nodes: [
        { id: 'n1', label: 'Cellular / Pre-Analytical Input', sublabel: mechanisms[0]?.slice(0, 62) || summary.slice(0, 62), tone: 'amber' },
        { id: 'n2', label: 'Assay / Pathway Step', sublabel: labSpec.slice(0, 62), tone: 'blue' },
        { id: 'n3', label: 'Diagnostic Pattern', sublabel: clinical.slice(0, 62), tone: 'rose' },
      ],
      links: [
        { from: 'n1', to: 'n2', label: 'Specimen integrity & biomarker measurement' },
        { from: 'n2', to: 'n3', label: 'Differential interpretation & safety check' },
      ],
    },
    assetDisclosure: HAEM_ASSET_GAP,
    activity: {
      title: `Diagnostic Lab Panel & Smear Reasoning (${chapterTitle})`,
      kind: 'interpretation',
      prompt: `Analyze the teaching parameters for ${chapterTitle} (${labSpec}), exclude pre-analytical artefact, and state the single confirmatory external microscopy or assay check.`,
      keyTakeaway: clinical,
    },
    readingKeys: ['ap_ch18_blood', 'utah_webpath'],
    shortAnswers: [
      { id: `sa-m${num}-1`, prompt: `Outline the core cellular/biochemical pathway in ${chapterTitle}.`, expectedPoints: mechanisms.slice(0, 2), modelAnswer: mechanisms.join(' '), level: 'medical_foundations' },
      { id: `sa-m${num}-2`, prompt: `Contrast ${comp.colA} versus ${comp.colB} diagnostically.`, expectedPoints: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator}`), modelAnswer: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator} (${r.clinicalOrFunctionalNote}).`).join(' '), level: 'clinical_applied' },
      { id: `sa-m${num}-3`, prompt: `Explain a critical pre-analytical pitfall or clinical lab pattern in ${chapterTitle.toLowerCase()}.`, expectedPoints: [labSpec, clinical], modelAnswer: `${labSpec}. ${clinical}`, level: 'clinical_applied' },
    ],
    appliedCase: {
      id: `app-m${num}-1`,
      title: `Teaching Laboratory Panel Case: ${chapterTitle}`,
      scenario: `An educational lab reasoning exercise investigates ${summary.toLowerCase()} (${labSpec}).`,
      questions: ['Which laboratory value or morphological feature anchors the differential?', 'What pre-analytical or medication factor must be checked first?'],
      workedSolution: `${mechanisms[0]} Lab context: ${labSpec}. Clinical synthesis: ${clinical}`,
      level: 'clinical_applied',
      disclaimer: HAEM_DISCLAIMER,
    },
    selfChecks: mcqs,
    educationalDisclaimer: HAEM_DISCLAIMER,
  };
}

